// src/terms.ts
import { mkdir as mkdir17, readFile as readFile18, writeFile as writeFile13 } from "node:fs/promises";
import { join as join28 } from "node:path";
var TermStore = class {
  constructor(outputDir) {
    this.outputDir = outputDir;
  }
  filePath() {
    return join28(resolveOutputDir(this.outputDir), "terms.json");
  }
  async read() {
    try {
      const parsed = JSON.parse(await readFile18(this.filePath(), "utf8"));
      return Array.isArray(parsed.terms) ? parsed.terms : [];
    } catch {
      return [];
    }
  }
  async set(entries) {
    const ledger = await this.read();
    for (const entry of entries) {
      const term = entry.term.trim().slice(0, 100);
      if (term === "") continue;
      const index = ledger.findIndex((existing) => existing.term === term);
      if (index >= 0) ledger[index] = { term, reading: entry.reading.slice(0, 200), at: Date.now() };
      else ledger.push({ term, reading: entry.reading.slice(0, 200), at: Date.now() });
    }
    await mkdir17(resolveOutputDir(this.outputDir), { recursive: true });
    await writeFile13(this.filePath(), JSON.stringify({ terms: ledger }, null, 2), "utf8");
    return ledger;
  }
  /** 按句命中：返回文本中出现的术语及其读法。 */
  async match(text2) {
    const ledger = await this.read();
    return ledger.filter((entry) => text2.includes(entry.term));
  }
};

